from pathlib import Path
p=Path('/tmp/m37/src/index.html')
s=p.read_text()
# css root + settings css
s=s.replace('.modalbox pre{white-space:pre-wrap;', '.settings-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.setting-card{background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:13px}.setting-card label{display:flex;align-items:center;justify-content:space-between;gap:12px;color:var(--text);font-size:12px;font-weight:800}.setting-card input[type=color]{width:48px;height:32px;padding:2px;border:1px solid var(--line);border-radius:7px;background:var(--panel2);cursor:pointer}.settings-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.settings-note{font-size:11px;color:var(--muted);line-height:1.5;margin-top:8px}@media(max-width:700px){.settings-grid{grid-template-columns:1fr}}.modalbox pre{white-space:pre-wrap;')
# nav
old='<button data-page="standings">Standings</button></div>'
new='<button data-page="standings">Standings</button><button data-page="settings">Settings</button></div>'
s=s.replace(old,new)
# settings page before closing main
marker='</main>\n<aside class="right">'
page='''<div id="settingsPage" class="page"><div class="hero"><div class="eyebrow">APP SETTINGS</div><div class="title" style="font-size:22px">Appearance</div><div class="note">Customize the sportsbook colors. Changes apply instantly and are saved locally. The current M27 BOOK theme is the default.</div></div><div class="settings-grid"><div class="setting-card"><label>Background <input type="color" data-theme-key="bg"></label></div><div class="setting-card"><label>Panel <input type="color" data-theme-key="panel"></label></div><div class="setting-card"><label>Panel 2 <input type="color" data-theme-key="panel2"></label></div><div class="setting-card"><label>Border / Lines <input type="color" data-theme-key="line"></label></div><div class="setting-card"><label>Main Text <input type="color" data-theme-key="text"></label></div><div class="setting-card"><label>Muted Text <input type="color" data-theme-key="muted"></label></div><div class="setting-card"><label>Accent <input type="color" data-theme-key="accent"></label></div><div class="setting-card"><label>Danger <input type="color" data-theme-key="danger"></label></div><div class="setting-card"><label>Gold <input type="color" data-theme-key="gold"></label></div></div><div class="settings-actions"><button class="btn primary" id="saveThemeBtn">Save Theme</button><button class="btn" id="resetThemeBtn">Reset Default</button></div><div class="settings-note">Theme settings are stored on this PC for this sportsbook app and do not modify your Madden Franchise save.</div></div>\n'''
s=s.replace(marker,page+marker)
# version footer
s=s.replace('Prototype 1.5.37 • Offline','Prototype 1.5.38 • Offline')
# insert theme JS after freshEconomy
needle="function freshEconomy(){return {date:todayKey(),checkIn:false,triviaIds:[],answers:{},perfectPaid:false,filmClicks:0,lastFilmClick:0,triviaVersion:3}}"
theme="""\nconst THEME_KEY='m27_sportsbook_theme_v1';\nconst DEFAULT_THEME={bg:'#080c11',panel:'#10161e',panel2:'#151d27',line:'#273240',text:'#edf2f7',muted:'#8d99a8',accent:'#35d07f',danger:'#ff6574',gold:'#f0c75e'};\nlet theme={...DEFAULT_THEME};\nfunction applyTheme(next){theme={...DEFAULT_THEME,...next};Object.entries(theme).forEach(([k,v])=>document.documentElement.style.setProperty('--'+k,v));document.querySelectorAll('[data-theme-key]').forEach(i=>{if(theme[i.dataset.themeKey])i.value=theme[i.dataset.themeKey]});}\nfunction loadTheme(){try{const saved=JSON.parse(localStorage.getItem(THEME_KEY)||'null');applyTheme(saved&&typeof saved==='object'?saved:DEFAULT_THEME)}catch{applyTheme(DEFAULT_THEME)}}\nfunction saveTheme(){localStorage.setItem(THEME_KEY,JSON.stringify(theme));setStatus('Theme saved.','ok')}\nfunction resetTheme(){applyTheme(DEFAULT_THEME);localStorage.removeItem(THEME_KEY);setStatus('Theme reset to the default M27 BOOK colors.','ok')}\nfunction initThemeControls(){document.querySelectorAll('[data-theme-key]').forEach(i=>i.addEventListener('input',()=>{theme[i.dataset.themeKey]=i.value;document.documentElement.style.setProperty('--'+i.dataset.themeKey,i.value)}));document.getElementById('saveThemeBtn')?.addEventListener('click',saveTheme);document.getElementById('resetThemeBtn')?.addEventListener('click',resetTheme);}\n"""
s=s.replace(needle,needle+theme)
# init calls before loadState
s=s.replace('loadState();document.body.classList.add', 'loadTheme();initThemeControls();loadState();document.body.classList.add')
p.write_text(s)
